import{c as t,Q as n,j as o,m as a}from"./chunks/framework.3U2mntTB.js";const p=JSON.parse('{"title":"World Mutation (Post-Gen)","description":"","frontmatter":{},"headers":[],"relativePath":"world-mutation.md","filePath":"world-mutation.md"}'),r={name:"world-mutation.md"};function s(i,e,l,d,c,h){return n(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="world-mutation-post-gen" tabindex="-1">World Mutation (Post-Gen) <a class="header-anchor" href="#world-mutation-post-gen" aria-label="Permalink to &quot;World Mutation (Post-Gen)&quot;">​</a></h1><p>Mirrors the FAWE QueueExtent + ChunkHolder runtime, but in plain Bukkit/Paper so we don&#39;t depend on FAWE.</p><p>Reference FAWE source: <code>other repos/FastAsyncWorldEdit-main/</code></p><h2 id="fawe-concept-→-aetheruhc-implementation" tabindex="-1">FAWE concept → AetherUHC implementation <a class="header-anchor" href="#fawe-concept-→-aetheruhc-implementation" aria-label="Permalink to &quot;FAWE concept → AetherUHC implementation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>FAWE</th><th>AetherUHC</th></tr></thead><tbody><tr><td><code>QueueHandler.blockingExecutor</code></td><td><code>AsyncSquareFillEngine</code> semaphore</td></tr><tr><td><code>getChunkAtAsync</code> + ticket</td><td><code>ChunkRegionRunner</code> warmup window + <code>ChunkTicketScope</code> plugin tickets</td></tr><tr><td>TPS budget in <code>QueueHandler.run()</code></td><td><code>MutationBudget</code> MSPT defer</td></tr><tr><td><code>ParallelQueueExtent</code> per-chunk flush</td><td><code>ChunkRegionRunner</code> per-chunk processing</td></tr></tbody></table><h2 id="post-gen-architecture" tabindex="-1">Post-gen architecture <a class="header-anchor" href="#post-gen-architecture" aria-label="Permalink to &quot;Post-gen architecture&quot;">​</a></h2><p>The original Skripts (<code>-bigcrack.sk</code>, <code>cu.sk</code>, <code>up.sk</code>) just wrote blocks one at a time with <code>set block to air</code> — fine for small maps because they sync-loaded chunks on demand, but on a 1600-radius map that watchdogs the server.</p><p>We port that exact block-write logic, but route every write through <code>ChunkRegionRunner</code>:</p><ol><li>The runner holds an ordered list of chunk coords (everything the transform needs to touch).</li><li>Each tick it pins the cursor chunk + a warmup window (N chunks ahead) via Paper plugin tickets and schedules async loads.</li><li>It waits until the cursor chunk is a full <code>LevelChunk</code> (not a <code>ProtoChunk</code>).</li><li>It hands the loaded <code>Chunk</code> to the transform&#39;s per-chunk callback, which uses <code>Chunk#setBlockData</code> directly.</li><li>After the callback signals done, it releases the cursor ticket and advances.</li></ol><p>This avoids three failure modes we hit before:</p><ul><li><strong>Sync load watchdog</strong> — <code>world.getBlockAt(...).setType(...)</code> on an unloaded chunk blocks the main thread; the runner only writes after async load completes.</li><li><strong>Chunks unloading mid-write</strong> — without a plugin ticket, an async-loaded chunk can unload before the next tick; the runner pins until the chunk is fully processed.</li><li><strong>FAWE no-op flush</strong> — the FAWE reflection bridge silently no-ops on <code>flush()</code> when the queue isn&#39;t owned by an <code>EditSession</code>, so <code>tryFlushRegion</code> advanced the progress bar without writing any blocks. Post-gen no longer touches the FAWE bridge at all — direct <code>Chunk#setBlockData</code> actually mutates the world.</li></ul><h2 id="per-transform-iteration" tabindex="-1">Per-transform iteration <a class="header-anchor" href="#per-transform-iteration" aria-label="Permalink to &quot;Per-transform iteration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Transform</th><th>Skript loop</th><th>Java port</th></tr></thead><tbody><tr><td>Big Crack</td><td>Y slice → Z row → X strip</td><td>Chunk by chunk; per chunk: Y slice → Z → X within chunk∩crack rectangle</td></tr><tr><td>Chunk Apocalypse</td><td>Outer Z grid → inner X grid → chance% → Y/Z/X column delete</td><td>Cell roll (Skript-faithful); for hit cells route through runner over cell∩chunks, Y/Z/X delete</td></tr><tr><td>Underground Parallel</td><td>Cell grid → X/Z column → Y source band → mirror to dest 54 below</td><td>Cell-by-cell; per chunk in cell∩chunks: X/Z column → Y source → mirror writes (same chunk for source + dest)</td></tr><tr><td>Dragon Rush</td><td>Portal + scattered site loop</td><td>Site by site; pin 3×3 chunks around each site, wait for full load, paste template</td></tr></tbody></table><h2 id="config-worldmanagement-yml" tabindex="-1">Config (<code>worldmanagement.yml</code>) <a class="header-anchor" href="#config-worldmanagement-yml" aria-label="Permalink to &quot;Config (\`worldmanagement.yml\`)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WORLD-MUTATION:</span></span>
<span class="line"><span>  BLOCKS-PER-TICK: 12000          # cap blocks set per tick across all transforms</span></span>
<span class="line"><span>  MAX-MSPT: 50                    # defer when server tick exceeds this</span></span>
<span class="line"><span>  TICK-INTERVAL: 1                # ticks between scheduler runs (1 = every tick)</span></span>
<span class="line"><span>  DEFERRED-TICK-INTERVAL: 3       # slower interval when server is laggy</span></span>
<span class="line"><span>  ASYNC-CHUNK-WARMUP: true        # use Paper getChunkAtAsync (recommended; required for ticket flow)</span></span>
<span class="line"><span>  WARMUP-CHUNKS-AHEAD: 48         # chunk warmup window size (also caps tickets held at once)</span></span>
<span class="line"><span>  USE-FAWE: auto                  # FAWE bridge is initialized but post-gen no longer uses it</span></span>
<span class="line"><span>  CHUNK-APOCALYPSE-MAX-COLUMNS-PER-TICK: 4</span></span>
<span class="line"><span>  DRAGON-RUSH-SITES-PER-TICK: 2</span></span></code></pre></div><h2 id="verifying-the-path" tabindex="-1">Verifying the path <a class="header-anchor" href="#verifying-the-path" aria-label="Permalink to &quot;Verifying the path&quot;">​</a></h2><ol><li>Check the post-gen log line for the transform: <ul><li><code>[Post-Gen] Big Crack carving N chunks (X chunks ..., Z chunks ...), 384 Y slices, budget 12000 blocks/tick.</code></li><li><code>[Post-Gen] Chunk Apocalypse: N cells (step 16, 5% delete), Y -64..319.</code></li><li><code>[Post-Gen] Underground Parallel: N cells (step 16), Mirror + bedrock seal.</code></li></ul></li><li>Watch the progress lines tick up by chunk/cell. If they stall on the same chunk for &gt;30s, the cursor chunk isn&#39;t reaching <code>LevelChunk</code> status — check Paper&#39;s chunk system load.</li><li>Visit the world; blocks should actually be air/mirrored.</li></ol><h2 id="border-defaults" tabindex="-1">Border defaults <a class="header-anchor" href="#border-defaults" aria-label="Permalink to &quot;Border defaults&quot;">​</a></h2><p>The standard UHC start border is <strong>2000 blocks</strong> (<code>BORDER.START: 2000</code> in <code>uhcconfiguration.yml</code>). This value is divisible by 16, giving a clean 125-chunk radius (~63,001 chunks in the pregen square). All modern testing and post-gen uses <code>BorderManager.getStartBorder()</code> → <code>BORDER.START</code> as <code>mapRadius</code>.</p><p>Non-divisible-by-16 values (e.g. 1750) still work — the Underground Parallel transform now clamps partial edge cells instead of refusing to run — but 2000 avoids edge cases entirely.</p><h2 id="uhc-world-used-trigger" tabindex="-1"><code>UHC-WORLD-USED</code> trigger <a class="header-anchor" href="#uhc-world-used-trigger" aria-label="Permalink to &quot;\`UHC-WORLD-USED\` trigger&quot;">​</a></h2><p>Pregen only runs when <code>UHC-WORLD-USED: true</code> in <code>uhcconfiguration.yml</code>. The flow:</p><ol><li><code>WorldsManager.startLoading()</code> checks <code>isMapUsed()</code>.</li><li>If <code>true</code> → delete old world → recreate → <code>scheduleWorldBorderFill(worldName, borderSize)</code> → pregen starts.</li><li>If <code>false</code> → load existing world, skip pregen.</li><li>On pregen completion, <code>onMapGenerationComplete()</code> sets <code>UHC-WORLD-USED: false</code> and saves config.</li></ol><p><strong>Common mistake</strong>: copying an old config with <code>UHC-WORLD-USED: false</code> to a fresh server — pregen never runs because the plugin thinks the world is already usable. Always set <code>true</code> when deploying a fresh map.</p><h2 id="pregen-optimizations-persistence-paper-26-1-legacy-1-8" tabindex="-1">Pregen Optimizations &amp; Persistence (Paper 26.1+ / Legacy 1.8) <a class="header-anchor" href="#pregen-optimizations-persistence-paper-26-1-legacy-1-8" aria-label="Permalink to &quot;Pregen Optimizations &amp; Persistence (Paper 26.1+ / Legacy 1.8)&quot;">​</a></h2><p>On modern and legacy versions, pregen speed and memory footprint are highly optimized through the following system:</p><ol><li><strong>Environment Suppression</strong>: Before pregen starts, <code>PregenEnvironmentManager</code> suppresses non-essential server tasks: disables mob spawning, disables daylight/weather cycles, disables fire tick/random tick speed, and slashes the server&#39;s view-distance/simulation-distance to 2 to minimize loaded neighbor chunks.</li><li><strong>Memory-efficient Iteration</strong>: Pregen uses a simple row-scan iterator instead of a spiral iterator. This significantly increases generation throughput and simplifies the math.</li><li><strong>Chunk Batching &amp; Periodic Saves</strong>: Previously, <code>AsyncSquareFillEngine</code> pinned all chunks for the entire duration of the pregen run. For large map sizes, this resulted in thousands of tickets held in memory, causing OOM crashes. The engine now batches chunk tickets (e.g., 2000 at a time) or saves based on a timer (<code>SAVE-INTERVAL-SECONDS</code>), flushes them to disk with <code>world.save()</code>, and releases the tickets.</li><li><strong>Urgent Priority</strong>: On Paper, <code>world.getChunkAtAsyncUrgently</code> is prioritized over the normal async chunk loading queue to squeeze maximum speed from the chunk generation threads.</li><li><strong>Disk Write Verification</strong>: The process finishes with a verification loop walking the expected coordinate grid to check <code>world.isChunkGenerated()</code> and logs any missing chunks.</li></ol><h2 id="server-level-tuning" tabindex="-1">Server-Level Tuning <a class="header-anchor" href="#server-level-tuning" aria-label="Permalink to &quot;Server-Level Tuning&quot;">​</a></h2><p>For maximum throughput during pregen, ensure your server configurations have the following:</p><p><strong>server.properties</strong></p><ul><li><code>sync-chunk-writes=false</code> (CRITICAL for chunk gen speed)</li><li><code>view-distance=2</code></li><li><code>simulation-distance=2</code></li></ul><h2 id="clean-slate-test-procedure" tabindex="-1">Clean-slate test procedure <a class="header-anchor" href="#clean-slate-test-procedure" aria-label="Permalink to &quot;Clean-slate test procedure&quot;">​</a></h2><p>To validate pregen from scratch on a test server (e.g. <code>test-server-26.1.2</code>):</p><ol><li>Stop the server.</li><li>Delete world data: <code>world/</code> (including <code>dimensions/minecraft/uhc_world*</code>), plus any <code>uhc_world</code> folders.</li><li>Reset plugin state: delete <code>plugins/AetherUHC/uhcconfiguration.yml</code> and <code>worldmanagement.yml</code> (or the entire <code>plugins/AetherUHC/</code> folder).</li><li>Set on the fresh config: <ul><li><code>BORDER.START: 2000</code></li><li><code>UHC-WORLD-USED: true</code></li><li><code>CHUNK-PREGENERATION.PREGEN-MODE: async</code></li></ul></li><li>Deploy new plugin JAR(s), start server.</li></ol><p><strong>Expected log sequence</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Map pregen mode from worldmanagement.yml: async (world=uhc_world, halfSize=2000)</span></span>
<span class="line"><span>Map pregen (async): concurrent=320, startsPerTick=128</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>World map generation finished.</span></span>
<span class="line"><span>Map pregen: verified 63001/63001 chunks on disk (0 missing)</span></span></code></pre></div><p><strong>Disk check</strong>: <code>world/dimensions/minecraft/uhc_world/region/</code> should have ~225 region files (chunk coords ±125 → region coords ±7, roughly 15×15).</p><p><strong>Post-gen smoke test</strong> (in order): Big Crack → Chunk Apocalypse → Underground Parallel; confirm visible world changes and no hang on chunk 1.</p>`,38)])])}const g=t(r,[["render",s]]);export{p as __pageData,g as default};
